/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    SalesLine salesLine;
    InventDim inventDim;

    while select ItemId, sum(SalesQty), sum(LineAmount) from salesLine
          group by ItemId, InventDimId
          join InventLocationId from inventDim
              group by InventLocationId
              where inventDim.InventDimId == salesLine.InventDimId
    {
        info(strFmt("Item: %1 | Warehouse: %2",
              salesLine.ItemId,
              inventDim.InventLocationId));
    }
}
